fprintf('x stats: mean=%.4g std=%.4g min=%.4g max=%.4g\n', mean(x), std(x), min(x), max(x));
% zero-padded FFT spectrum (fine resolution), Hann window
M = 2^nextpow2(max(N*8, 8192));
w = hann(N);
Xw = abs(fft((x-mean(x)).*w, M));
f = (0:M-1)'*fs/M;
half = f <= fs/2;
Xh = Xw(half); fh = f(half);
[~,i1] = max(Xh); fpeak_raw = fh(i1);
% parabolic interpolation for finer peak estimate
if i1>1 && i1<numel(Xh)
    a=log(Xh(i1-1)); b=log(Xh(i1)); c=log(Xh(i1+1));
    d=0.5*(a-c)/(a-2*b+c); fpeak_interp = fh(i1) + d*(fs/M);
else
    fpeak_interp = fpeak_raw;
end
fprintf('bin peak = %.4f Hz, interp peak = %.4f Hz\n', fpeak_raw, fpeak_interp);
